package com.minhnb.finvera_be.alert.entity;
import tools.jackson.databind.JsonNode;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="alert_evaluation") public class AlertEvaluationEntity{@Id private UUID id;@Column(name="alert_id")private UUID alertId;@Column(name="owner_id")private UUID ownerId;@Column(name="fact_key")private String factKey;@Column(name="fact_at")private Instant factAt;@Column(name="accepted_at")private Instant acceptedAt;@Column(name="evaluated_at")private Instant evaluatedAt;private String outcome;@Column(name="reason_code")private String reasonCode;@JdbcTypeCode(SqlTypes.JSON)@Column(name="evidence_snapshot",columnDefinition="jsonb")private JsonNode evidence;@Column(name="attempt_count")private short attemptCount;@Column(name="duration_ms")private int durationMs;protected AlertEvaluationEntity(){}public AlertEvaluationEntity(UUID id,UUID alertId,UUID ownerId,String factKey,Instant factAt,Instant acceptedAt,Instant evaluatedAt,String outcome,String reasonCode,JsonNode evidence,short attemptCount,int durationMs){this.id=id;this.alertId=alertId;this.ownerId=ownerId;this.factKey=factKey;this.factAt=factAt;this.acceptedAt=acceptedAt;this.evaluatedAt=evaluatedAt;this.outcome=outcome;this.reasonCode=reasonCode;this.evidence=evidence;this.attemptCount=attemptCount;this.durationMs=durationMs;}public UUID getId(){return id;}public UUID getAlertId(){return alertId;}public String getFactKey(){return factKey;}public Instant getFactAt(){return factAt;}public Instant getAcceptedAt(){return acceptedAt;}public Instant getEvaluatedAt(){return evaluatedAt;}public String getOutcome(){return outcome;}public String getReasonCode(){return reasonCode;}public JsonNode getEvidence(){return evidence;}public short getAttemptCount(){return attemptCount;}}
